// Des: Human input: eased mouse, hover click, rollover typing
// Flo: curved mouse path in small steps > press + release with pauses > one key at a time with random gaps > scroll in chunks
// I/O: Page + Rng + Conf + text or point (caller) > CDP Input events (trusted browser events, no script clicks)
// ===================================================================
const std = @import("std"); const pg = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .step_lo = 8, .step_hi = 16, .pre_lo = 100, .pre_hi = 600, .down_lo = 60, .down_hi = 140, .dwel_lo = 45, .dwel_hi = 130, .rol_lo = 12, .rol_hi = 40, .thnk_lo = 300, .thnk_hi = 900, .thnk_evy = 14, .spac_add = 60, .whel_lo = 100, .whel_hi = 160, .gap_lo = 16, .gap_hi = 48, .flik_lo = 150, .flik_hi = 450, .fit_a = 120.0, .fit_b = 150.0, .fit_w = 24.0, .fit_ms = 12.0, .land = 3.0, .roll_pct = 12, .digr_pct = 70, .long_txt = 240, .back_pct = 10, .back_min = 600.0, .tau = 6.283185307179586 };
const DIGR = [_][]const u8{ "th", "he", "in", "er", "an", "re", "on", "at", "en", "nd", "ti", "es", "or", "te", "of", "ed", "is", "it", "al", "ar", "st", "to", "nt", "ng", "se", "ha", "as", "ou", "io", "le", "ve", "co", "me", "de", "hi", "ri", "ro", "ic", "ne", "ea", "ra", "ce" };
pub const Env = struct { page: *pg.Page, rng: *pace.Rng, conf: cfgz.Conf, aren: std.mem.Allocator };
fn wait(env: *Env, lo: u64, hi: u64) void { env.page.nap(@intCast(pace.scaled(pace.logn(env.rng, lo, hi), env.conf.time_scal_perc))); }
fn waitPerc(env: *Env, lo: u64, hi: u64, perc: u32) void { env.page.nap(@intCast(pace.scaled(pace.scaled(pace.logn(env.rng, lo, hi), perc), env.conf.time_scal_perc))); }
fn mouse(env: *Env, kind: []const u8, xpos: f64, ypos: f64, down: bool) !void { const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .type = kind, .x = xpos, .y = ypos, .button = if (down or std.mem.eql(u8, kind, "mouseReleased")) "left" else "none", .clickCount = @as(u8, if (down or std.mem.eql(u8, kind, "mouseReleased")) 1 else 0) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchMouseEvent", prm); }
pub const Pt = struct { x: f64, y: f64 };
pub fn plan(aren: std.mem.Allocator, rng: *pace.Rng, sx: f64, sy: f64, tx: f64, ty: f64, capn: u32) ![]Pt { const dxx = tx - sx; const dyy = ty - sy; const dis = @sqrt(dxx * dxx + dyy * dyy); if (dis < 1.0) { const one = try aren.alloc(Pt, 1); one[0] = .{ .x = tx, .y = ty }; return one; } const fit = CF.fit_a + CF.fit_b * std.math.log2(dis / CF.fit_w + 1.0); const raw: u32 = @intFromFloat(fit / CF.fit_ms); const cnt = std.math.clamp(raw, 8, @max(8, capn)); const nx = -dyy / dis; const ny = dxx / dis; const amp = @min(14.0, 0.06 * dis); const j1 = (rng.unit() - 0.5) * 0.3 * dis; const j2 = (rng.unit() - 0.5) * 0.3 * dis; const a1 = 0.5 + rng.unit(); const a2 = 0.5 + rng.unit(); const a3 = 0.5 + rng.unit(); const p2 = rng.unit() * CF.tau; const p3 = rng.unit() * CF.tau; const c1x = sx + dxx * 0.3 + nx * j1; const c1y = sy + dyy * 0.3 + ny * j1; const c2x = sx + dxx * 0.7 + nx * j2; const c2y = sy + dyy * 0.7 + ny * j2; const out = try aren.alloc(Pt, cnt); for (out, 0..) |*pnt, pos| { const tpp = @as(f64, @floatFromInt(pos + 1)) / @as(f64, @floatFromInt(cnt)); const smo = tpp * tpp * tpp * (10.0 - 15.0 * tpp + 6.0 * tpp * tpp); const omt = 1.0 - smo; const bx = omt * omt * omt * sx + 3.0 * omt * omt * smo * c1x + 3.0 * omt * smo * smo * c2x + smo * smo * smo * tx; const by = omt * omt * omt * sy + 3.0 * omt * omt * smo * c1y + 3.0 * omt * smo * smo * c2y + smo * smo * smo * ty; const nzz = amp * @sin(std.math.pi * tpp) * (a1 + a2 * @sin(2.0 * std.math.pi * tpp + p2) / 2.0 + a3 * @sin(3.0 * std.math.pi * tpp + p3) / 3.0); pnt.* = .{ .x = bx + nx * nzz, .y = by + ny * nzz }; } out[cnt - 1] = .{ .x = tx, .y = ty }; return out; }
pub fn moveTo(env: *Env, tx: f64, ty: f64) !void { const pts = try plan(env.aren, env.rng, env.page.mx, env.page.my, tx, ty, env.conf.mous_step_coun * 3); for (pts) |pnt| { try mouse(env, "mouseMoved", pnt.x, pnt.y, false); wait(env, CF.step_lo, CF.step_hi); } env.page.mx = tx; env.page.my = ty; }
pub fn click(env: *Env, tx: f64, ty: f64) !void { const ox = (env.rng.unit() - 0.5) * 2.0 * CF.land; const oy = (env.rng.unit() - 0.5) * 2.0 * CF.land; try moveTo(env, tx + ox, ty + oy); wait(env, CF.pre_lo, CF.pre_hi); try mouse(env, "mousePressed", tx + ox, ty + oy, true); wait(env, CF.down_lo, CF.down_hi); try mouse(env, "mouseReleased", tx + ox, ty + oy, true); }
pub fn pressKey(env: *Env, name: []const u8) !void { const isen = std.mem.eql(u8, name, "Enter"); const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = name, .code = name, .windowsVirtualKeyCode = @as(u32, if (isen) 13 else 27), .text = @as([]const u8, if (isen) "\r" else "") }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", prm); const upz = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = name, .code = name, .windowsVirtualKeyCode = @as(u32, if (isen) 13 else 27) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", upz); }
fn keyDown(env: *Env, chr: u8) !void { var one: [1]u8 = .{chr}; const down = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = @as([]const u8, &one), .text = @as([]const u8, &one) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", down); }
fn keyUp(env: *Env, chr: u8) !void { var one: [1]u8 = .{chr}; const upz = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = @as([]const u8, &one) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", upz); }
fn keyChar(env: *Env, chr: u8) !void { try keyDown(env, chr); wait(env, CF.dwel_lo, CF.dwel_hi); try keyUp(env, chr); }
fn plain(sli: []const u8) bool { return sli.len == 1 and sli[0] >= 32 and sli[0] < 127; }
fn sliceAt(text: []const u8, idx: usize) []const u8 { const lenz = std.unicode.utf8ByteSequenceLength(text[idx]) catch 1; return text[idx..@min(idx + lenz, text.len)]; }
pub fn common(one: u8, two: u8) bool { const pair = [2]u8{ std.ascii.toLower(one), std.ascii.toLower(two) }; for (DIGR) |dig| { if (std.mem.eql(u8, dig, &pair)) return true; } return false; }
fn insChar(env: *Env, txt: []const u8) !void { const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .text = txt }, .{}); _ = try env.page.call(env.aren, "Input.insertText", prm); }
pub fn typeText(env: *Env, text: []const u8) !void { if (text.len > CF.long_txt) { wait(env, CF.thnk_lo, CF.thnk_hi); try insChar(env, text); wait(env, CF.thnk_lo, CF.thnk_hi); return; } var idx: usize = 0; var cnt: u32 = 0; var prev: u8 = 0; while (idx < text.len) { const sli = sliceAt(text, idx); var adv = sli.len; var last: u8 = 0; if (plain(sli)) { last = sli[0]; const nxs = if (idx + sli.len < text.len) sliceAt(text, idx + sli.len) else ""; if (plain(nxs) and env.rng.span(0, 99) < CF.roll_pct) { try keyDown(env, sli[0]); wait(env, CF.rol_lo, CF.rol_hi); try keyDown(env, nxs[0]); wait(env, CF.dwel_lo, CF.dwel_hi); try keyUp(env, sli[0]); wait(env, CF.rol_lo, CF.rol_hi); try keyUp(env, nxs[0]); adv += nxs.len; last = nxs[0]; cnt += 1; } else { try keyChar(env, sli[0]); } } else if (sli.len == 1 and sli[0] == '\n') { try pressKey(env, "Enter"); } else { try insChar(env, sli); } cnt += 1; const fast = prev != 0 and last != 0 and common(prev, last); waitPerc(env, env.conf.type_dely_msec[0], env.conf.type_dely_msec[1], if (fast) CF.digr_pct else 100); if (last == ' ') wait(env, CF.spac_add, CF.spac_add * 3); if (cnt % CF.thnk_evy == 0) wait(env, CF.thnk_lo, CF.thnk_hi); prev = last; idx += adv; } }
pub fn clearField(env: *Env) !void { const dwn = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = "a", .code = "KeyA", .windowsVirtualKeyCode = @as(u32, 65), .modifiers = @as(u32, 2), .commands = [_][]const u8{"selectAll"} }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", dwn); const upz = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = "a", .code = "KeyA", .windowsVirtualKeyCode = @as(u32, 65), .modifiers = @as(u32, 2) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", upz); wait(env, CF.rol_lo, CF.rol_hi); const bkd = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyDown", .key = "Backspace", .code = "Backspace", .windowsVirtualKeyCode = @as(u32, 8) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", bkd); const bku = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "keyUp", .key = "Backspace", .code = "Backspace", .windowsVirtualKeyCode = @as(u32, 8) }, .{}); _ = try env.page.call(env.aren, "Input.dispatchKeyEvent", bku); }
fn wheel(env: *Env, dy: f64) !void { const prm = try std.json.Stringify.valueAlloc(env.aren, .{ .type = "mouseWheel", .x = env.page.mx + 5.0, .y = env.page.my + 5.0, .deltaX = @as(f64, 0), .deltaY = dy }, .{}); _ = try env.page.call(env.aren, "Input.dispatchMouseEvent", prm); }
pub fn flickPlan(aren: std.mem.Allocator, rng: *pace.Rng, dist: f64) ![]f64 { const sign: f64 = if (dist < 0) -1.0 else 1.0; var out: std.ArrayList(f64) = .empty; var done: f64 = 0; var chunk: f64 = @floatFromInt(rng.span(CF.whel_lo, CF.whel_hi)); while (done < @abs(dist)) { try out.append(aren, chunk * sign); done += chunk; chunk *= 0.78 + rng.unit() * 0.12; if (chunk < 20.0) chunk = @floatFromInt(rng.span(CF.whel_lo, CF.whel_hi)); } return out.items; }
fn flick(env: *Env, dist: f64) !void { const chunks = try flickPlan(env.aren, env.rng, dist); for (chunks, 0..) |chk, idx| { try wheel(env, chk); if (idx + 1 < chunks.len and @abs(chunks[idx + 1]) > @abs(chk)) wait(env, CF.flik_lo, CF.flik_hi) else wait(env, CF.gap_lo, CF.gap_hi); } }
pub fn scrollBy(env: *Env, total: f64) !void { try flick(env, total); if (@abs(total) >= CF.back_min and env.rng.span(0, 99) < CF.back_pct) { const back: f64 = @floatFromInt(env.rng.span(60, 140)); wait(env, CF.flik_lo, CF.flik_hi); try flick(env, if (total > 0) -back else back); wait(env, CF.flik_lo, CF.flik_hi); try flick(env, if (total > 0) back else -back); } }
